// Build Product Documents from Products sheet rows.
// Columns: product_id, name, category, size, color, price, stock,
//          description, image_url, status
const items = $input.all();
const out = [];
for (const it of items) {
  const p = it.json;
  const status = (p.status || '').toString().trim().toLowerCase();
  if (status && status !== 'active') continue;          // skip inactive
  const name = (p.name || '').toString().trim();
  if (!name) continue;                                  // skip blank rows
  const id = (p.product_id || `prd-${out.length+1}`).toString().trim();
  const lines = [
    `Type: Product`,
    `Product ID: ${id}`,
    `Name: ${name}`,
    `Category: ${p.category || ''}`,
    `Size: ${p.size || ''}`,
    `Color: ${p.color || ''}`,
    `Price: ${p.price ?? ''}`,
    `Stock: ${p.stock ?? ''}`,
    `Status: ${p.status || ''}`,
    `Description: ${p.description || ''}`,
  ].filter(l => (l.split(': ')[1] || '').toString().trim() !== '');
  out.push({ json: {
    content: lines.join('\n'),
    metadata: {
      id: `product-${id}`,                              // stable Pinecone id
      source: 'products_sheet',
      type: 'product',
      product_id: id,
      name: name,
      category: (p.category || '').toString()
    }
  }});
}
return out;

// Build Setup Documents from Setup sheet rows.
// Columns: key, value, notes
// SECURITY: skip rows whose key looks like a token/secret OR whose value
// is empty. Operational rules (REPLY_STYLE, MAX_MEMORY_TURNS, etc.)
// are kept and indexed as bot configuration knowledge.
const items = $input.all();
const out = [];
const SECRET_RX = /(token|secret|password|api[_ ]?key|sheet[_ ]?id|chat[_ ]?id)/i;
const ALLOW_RX  = /(reply|style|memory|max|tone|language|hour|policy|rule|instruction|behavior|prompt)/i;
for (const it of items) {
  const s = it.json;
  const key = (s.key || '').toString().trim();
  const val = (s.value === 0 ? '0' : (s.value || '').toString()).trim();
  if (!key || !val) continue;                           // skip blanks
  if (SECRET_RX.test(key) && !ALLOW_RX.test(key)) continue;  // skip secrets
  const notes = (s.notes || '').toString().trim();
  const stableId = key.toLowerCase().replace(/[^a-z0-9]+/g, '_');
  const lines = [
    `Type: Setup`,
    `Key: ${key}`,
    `Value: ${val}`,
    notes ? `Notes: ${notes}` : '',
  ].filter(Boolean);
  out.push({ json: {
    content: lines.join('\n'),
    metadata: {
      id: `setup-${stableId}`,                          // stable Pinecone id
      source: 'setup_sheet',
      type: 'setup',
      key: key
    }
  }});
}
return out;
